 // Two real transactions hold the common physical fence before the second command starts.
 // The barrier fixes the serial order; it does not rely on timing or thread sleeps.
 Map<String,Object> race(Map<String,Object> first,Map<String,Object> second)throws Exception{
  var firstPid=new java.util.concurrent.atomic.AtomicInteger();var firstLocked=new java.util.concurrent.CountDownLatch(1);var secondStarted=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var security=SecurityContextHolder.getContext().getAuthentication();var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
  try{var one=pool.submit(()->{SecurityContextHolder.getContext().setAuthentication(security);return tx(()->{inventory.fence(c(),stock.fences(inventory.current(c(),"QuantitySegments",segment)));firstPid.set(jdbc.queryForObject("SELECT pg_backend_pid()",Integer.class));firstLocked.countDown();await(release);return apply(first);});});assertTrue(firstLocked.await(10,java.util.concurrent.TimeUnit.SECONDS));var two=pool.submit(()->{SecurityContextHolder.getContext().setAuthentication(security);secondStarted.countDown();return apply(second);});assertTrue(secondStarted.await(10,java.util.concurrent.TimeUnit.SECONDS));long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);List<Integer> waiters=List.of();while(System.nanoTime()<deadline){waiters=jdbc.queryForList("SELECT pid FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND ? = ANY(pg_blocking_pids(pid))",Integer.class,firstPid.get());if(!waiters.isEmpty())break;Thread.onSpinWait();}
  // Lock-wait proof from a third connection: the competing statement is parked on an ungranted lock held by the first transaction.
  assertEquals(1,waiters.size(),"Second PostgreSQL transaction must be lock-blocked by first before barrier release");assertFalse(two.isDone());assertTrue(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_locks WHERE pid=? AND NOT granted)",Boolean.class,waiters.getFirst()));assertTrue(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_locks WHERE pid=? AND granted AND locktype IN ('advisory','transactionid','tuple','relation'))",Boolean.class,firstPid.get()));release.countDown();assertEquals("APPLIED",one.get(20,java.util.concurrent.TimeUnit.SECONDS).get("outcome"));return two.get(20,java.util.concurrent.TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();}
 }
 void await(java.util.concurrent.CountDownLatch latch){try{if(!latch.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("Barrier timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}
