 <T> T as(String subject,java.util.function.Supplier<T> work){var previous=SecurityContextHolder.getContext().getAuthentication();SecurityContextHolder.getContext().setAuthentication(new JwtAuthenticationToken(Jwt.withTokenValue("local-test").header("alg","RS256").issuer("https://fixture.invalid").subject(subject).claim("organizationId",org).build(),List.of()));try{return work.get();}finally{SecurityContextHolder.getContext().setAuthentication(previous);}}
 String canonicalOf(String claim){return jdbc.queryForObject("SELECT canonicalOccurrenceId FROM mulino_evidence_Verifications WHERE claimId=?",String.class,claim);}
 /** Explicit version N of the same carrier event superseding the current one; the product verifies and links it. */
 String[] correctDelivery(Map<String,Object> content,String external,String deliveryId,String previousEvent,String q,int version){try{now=now.plusSeconds(1);/* an immutable supersession is recorded strictly after its predecessor */var corrected=new LinkedHashMap<String,Object>(content);corrected.put("quantity",q);corrected.put("correctionOfDeliveryId",deliveryId);String bytes=json.writeValueAsString(corrected);var subject=map("kind","DISPATCH","id",content.get("dispatchId"));
  var doc=run("attachEvidence",map("subject",subject,"sourceNamespace","quality-source","sourceReference",id(),"mediaType","application/json","expectedHash",com.mulino.adapters.blob.LocalBlobStore.hash(bytes.getBytes()),"provenance","SYNTHETIC","contentBase64",Base64.getEncoder().encodeToString(bytes.getBytes())),null).get("id").toString();
  var event=run("correctEvidence",map("subject",subject,"kind","PHYSICAL_DELIVERY","sourceNamespace","quality-source","externalEventId",external,"sourceVersion",String.valueOf(version),"effectiveFrom",content.get("occurredAt"),"timeZone","UTC","timePrecision","SECOND","valueState","KNOWN","payload",bytes,"supersedesId",previousEvent,"documentId",doc,"assertion","Explicit actual delivery correction","quantity",q,"unit","EA","evidenceType","EVENT"),version-1);
  String claim=event.get("claimId").toString();var review=apply(envelope("matchSourceIdentity",map("claimId",claim,"basisDocumentId",doc,"physicalScopeId",content.get("physicalScopeId"),"policyVersion","fixture-v1","sourceIdentity","quality-source:"+external+":"+version,"quantity",q,"unit","EA","effectiveFrom",content.get("occurredAt"),"reason","Synthetic delivery correction review"),1));assertEquals("APPLIED",review.get("outcome"),review.toString());run("linkCanonicalOccurrence",map("reconciliationId",review.get("id")),1);
  return new String[]{canonicalOf(claim),event.get("id").toString()};}catch(Exception e){throw new IllegalStateException(e);}}
 Map<String,Object> deficit(String status){return jdbc.queryForList("SELECT * FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status=? ORDER BY createdAt,ID",status).stream().findFirst().orElse(null);}
 int count(String sql,Object...args){return jdbc.queryForObject(sql,Integer.class,args);}
 Map<String,Object> waiverDecision(String subject,String cap,String assignment,String decision,String reason){return as(subject,()->apply(envelope(cap,map("assignmentId",assignment,"decision",decision,"reason",reason,"validUntil",now.plusSeconds(600).toString()),revision(assignment))));}
 int revision(String assignment){return count("SELECT revision FROM mulino_work_read_ObligationReferences WHERE ID=?",assignment);}
 Map<String,Object> waive(String assignment,String reason,String approval,String key){var i=envelope("waiveObligation",map("assignmentId",assignment,"reason",reason),revision(assignment));i.put("commandIdempotencyKey",key);if(approval!=null)i.put("approvalId",approval);return apply(i);}
 Map<String,Object> resolve(String assignment,String evidence){return apply(envelope("resolveObligation",map("assignmentId",assignment,"evidenceId",evidence),revision(assignment)));}
 String code(Map<String,Object> r){return ((Map<?,?>)r.get("error")).get("code").toString();}

 // C4/D12/D24: actual 98-style correction leaves the past delivery and a current deficit duty. It closes only by the current
 // verified delivery that restores its exact range, or by a typed single-use MANAGER waiver bound to this duty revision;
 // a waived duty is never revived by reprocessing, while a genuinely new deficit creates a new duty.
 @Test void correctedDeliveryDeficitClosesOnlyByVerifiedRestorationOrTypedManagerWaiverAndIsNotRevived(){allow("100");allowDispatch();String dispatch=dispatched("0","30");
  var content=deliveryReport(dispatch,"0","30",destination);String ids=intakeDelivery(content);var review=matchDelivery(content,ids);assertEquals("APPLIED",review.get("outcome"),review.toString());run("linkCanonicalOccurrence",map("reconciliationId",review.get("id")),1);String original=canonicalOf(ids.split("\\|")[0]);var delivered=effects(run("recordDelivery",map("observationId",content.get("physicalScopeId"),"canonicalOccurrenceId",original),1));assertEquals("30",delivered.get("physicalQuantity"));
  String deliveryId=jdbc.queryForObject("SELECT ID FROM mulino_trade_sales_Deliveries WHERE observationId=?",String.class,content.get("physicalScopeId"));String event1=jdbc.queryForObject("SELECT eventId FROM mulino_evidence_Claims WHERE ID=?",String.class,ids.split("\\|")[0]);String external=ids.split("\\|")[2];
  // Delivery ends our warehouse custody; ownership is not transferred by the handover (plan §4.2).
  var customerLeaf=jdbc.queryForMap("SELECT custodianId,ownerId FROM mulino_inventory_QuantitySegments WHERE placeId=? AND retiredAt IS NULL",destination);assertNull(customerLeaf.get("custodianid"));assertEquals(actor,customerLeaf.get("ownerid"));
  var v2=correctDelivery(content,external,deliveryId,event1,"28",2);
  var duty=deficit("OPEN");assertNotNull(duty);assertEquals(0,new BigDecimal("2").compareTo((BigDecimal)duty.get("quantity")));String assignment=duty.get("id").toString();
  assertEquals(0,new BigDecimal("30").compareTo(sum("SELECT SUM(quantity) FROM mulino_trade_sales_Deliveries")));
  // Wrong evidence: the correction that created the deficit, or the superseded original delivery, cannot fulfil it.
  for(String wrong:List.of(v2[0],original)){var r=resolve(assignment,wrong);assertEquals("HELD",r.get("outcome"),r.toString());assertEquals("OPEN",deficit("OPEN").get("status"));}
  assertEquals(0,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status<>'OPEN'"));
  // Waiver without an approval, without designation, by the wrong authority class, or with a REJECT decision has no effect.
  var bare=waive(assignment,"고객이 부족2를 수용했다",null,id());assertEquals("REJECTED",bare.get("outcome"),bare.toString());
  var undesignated=waiverDecision("quality","decideQuantityDutyWaiver",assignment,"APPROVE","고객이 부족2를 수용했다");assertEquals("REJECTED",undesignated.get("outcome"),undesignated.toString());
  var wrongClass=waiverDecision("manager","decideQualityDutyWaiver",assignment,"APPROVE","고객이 부족2를 수용했다");assertEquals("REJECTED",wrongClass.get("outcome"),wrongClass.toString());
  var rejected=effectsOf(waiverDecision("manager","decideQuantityDutyWaiver",assignment,"REJECT","근거 부족"));assertEquals("REJECTED",rejected.get("decision"));
  var usingRejected=waive(assignment,"근거 부족",rejected.get("approvalId").toString(),id());assertEquals("REJECTED",usingRejected.get("outcome"),usingRejected.toString());
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_commands_Approvals WHERE targetId=? AND decision='REJECTED'",assignment));
  // Stale: an approval bound to the duty revision cannot be reused after the responsibility moved (owner handover).
  var stale=effectsOf(waiverDecision("manager","decideQuantityDutyWaiver",assignment,"APPROVE","고객이 부족2를 수용했다"));
  int workRevision=count("SELECT revision FROM mulino_work_read_Works WHERE ID=?",work);var proposed=effectsOf(apply(envelope("proposeHandover",map("workId",work,"recipientId",manager,"expiresAt",now.plusSeconds(600).toString(),"nextAction","부족2 대응을 인수한다","nextCheckAt",now.plusSeconds(300).toString()),workRevision)));
  var accepted=as("manager",()->apply(envelope("acceptHandover",map("handoverId",proposed.get("ID")),0)));assertEquals("APPLIED",accepted.get("outcome"),accepted.toString());
  var staleUse=waive(assignment,"고객이 부족2를 수용했다",stale.get("approvalId").toString(),id());assertEquals("REJECTED",staleUse.get("outcome"),staleUse.toString());assertEquals("OPEN",deficit("OPEN").get("status"));
  // Changed reason is a different intent hash: no effect.
  var approval=effectsOf(waiverDecision("manager","decideQuantityDutyWaiver",assignment,"APPROVE","고객이 부족2를 수용했다"));assertEquals("APPROVED",approval.get("decision"));
  var changed=waive(assignment,"다른 사유",approval.get("approvalId").toString(),id());assertEquals("REJECTED",changed.get("outcome"),changed.toString());assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status='OPEN'"));
  var waiveRequest=envelope("waiveObligation",map("assignmentId",assignment,"reason","고객이 부족2를 수용했다"),revision(assignment));waiveRequest.put("approvalId",approval.get("approvalId"));var waived=apply(waiveRequest);assertEquals("APPLIED",waived.get("outcome"),waived.toString());
  var replay=apply(waiveRequest);assertEquals("APPLIED",replay.get("outcome"),replay.toString());assertEquals(waived.get("commandId"),replay.get("commandId"),replay.toString());
  var reuse=waive(assignment,"고객이 부족2를 수용했다",approval.get("approvalId").toString(),id());assertNotEquals("APPLIED",reuse.get("outcome"),reuse.toString());
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE ID=? AND status='WAIVED' AND evidenceId=?",assignment,approval.get("approvalId")));assertEquals(1,count("SELECT COUNT(*) FROM mulino_commands_ApprovalConsumptions WHERE approvalId=?",approval.get("approvalId")));
  // Reprocessing the same correction and a further correction to the same 28 do not revive the waived duty.
  var again=runtime.requestContext().run(ctx->{return new org.springframework.transaction.support.TransactionTemplate(transactions).execute(st->corrections.correctionImpact(c(),deliveryId,v2[0]));});assertEquals(true,again.get("duplicate"));
  var v3=correctDelivery(content,external,deliveryId,v2[1],"28",3);
  assertEquals(0,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status='OPEN'"));assertEquals(1,count("SELECT COUNT(*) FROM mulino_responsibility_Roots WHERE kind='DELIVERY_CORRECTED_DEFICIT'"));assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status='WAIVED'"));
  // A genuinely new deficit (actual 27) is a new duty of 1; restoring the actual to 30 is the verified fulfilment of it.
  var v4=correctDelivery(content,external,deliveryId,v3[1],"27",4);var second=deficit("OPEN");assertNotNull(second);assertEquals(0,BigDecimal.ONE.compareTo((BigDecimal)second.get("quantity")));assertEquals(2,count("SELECT COUNT(*) FROM mulino_responsibility_Roots WHERE kind='DELIVERY_CORRECTED_DEFICIT'"));
  var v5=correctDelivery(content,external,deliveryId,v4[1],"30",5);
  var superseded=resolve(second.get("id").toString(),v4[0]);assertEquals("HELD",superseded.get("outcome"),superseded.toString());
  var resolved=resolve(second.get("id").toString(),v5[0]);assertEquals("APPLIED",resolved.get("outcome"),resolved.toString());
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE ID=? AND status='RESOLVED' AND evidenceId=?",second.get("id"),v5[0]));assertEquals(0,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='DELIVERY_CORRECTED_DEFICIT' AND status='OPEN'"));
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE ID=? AND status='WAIVED'",assignment));assertEquals(0,new BigDecimal("30").compareTo(sum("SELECT SUM(quantity) FROM mulino_trade_sales_Deliveries")));}
 /** s4i closure 2 (plan §6 정산 "정산 차이는 별도 미해결 목표", §4.3, §5.3): a verified post-match delivery correction opens an owned
  * SETTLEMENT_DIFFERENCE keyed to the correcting canonical in the same transaction. Waiving the logistics deficit leaves that
  * settlement duty OPEN with owner and next action, and the adjustment path is no longer rejected as NOT_OPEN. */
 @Test void postMatchDeliveryCorrectionOpensOwnedSettlementDifferenceThatSurvivesTheDeficitWaiver(){allow("100");allowDispatch();String dispatch=dispatched("0","30");
  var content=deliveryReport(dispatch,"0","30",destination);String ids=intakeDelivery(content);var review=matchDelivery(content,ids);assertEquals("APPLIED",review.get("outcome"),review.toString());run("linkCanonicalOccurrence",map("reconciliationId",review.get("id")),1);String original=canonicalOf(ids.split("\\|")[0]);run("recordDelivery",map("observationId",content.get("physicalScopeId"),"canonicalOccurrenceId",original),1);
  String deliveryId=jdbc.queryForObject("SELECT ID FROM mulino_trade_sales_Deliveries WHERE observationId=?",String.class,content.get("physicalScopeId"));String event1=jdbc.queryForObject("SELECT eventId FROM mulino_evidence_Claims WHERE ID=?",String.class,ids.split("\\|")[0]);String external=ids.split("\\|")[2];
  var source=map("sourceNamespace","quality-source","sourceKey",id(),"sourceVersion","1","lineId",salesLine,"referenceId",deliveryId,"scopeKind","SALE","invoiceKind","COMMERCIAL","itemId",item,"quantity","30","unit","EA","unitPrice","1","originalAmount","30","currency","KRW","occurredAt",now.toString());String bytes=write(source);
  String invoiceDoc=attachJson(map("kind","SALES_ORDER_LINE","id",salesLine),bytes);
  var invoice=effects(run("recordInvoice",map("invoiceKind","COMMERCIAL","originalAmount",map("value","30","currency","KRW"),"scopeKind","SALE","line",map("saleLineId",salesLine,"deliveryId",deliveryId,"quantity",map("value","30","unit","EA"),"unitPrice",map("value","1","currency","KRW")),"evidence",invoiceDoc),1));String iid=invoice.get("invoiceId").toString();
  String[] proof=invoiceFact(iid,"INVOICE",bytes,"30");var matched=run("matchInvoice",map("invoiceId",iid,"canonicalOccurrenceId",proof[1],"evidence",proof[0]),1);assertEquals("MATCHED",matched.get("businessStatus"),matched.toString());
  assertEquals(0,count("SELECT COUNT(*) FROM mulino_responsibility_Roots WHERE kind='SETTLEMENT_DIFFERENCE'"));
  var v2=correctDelivery(content,external,deliveryId,event1,"28",2);
  var settlementDuty=jdbc.queryForList("SELECT o.* FROM mulino_work_read_ObligationReferences o JOIN mulino_responsibility_Roots r ON r.ID=o.rootId WHERE o.kind='SETTLEMENT_DIFFERENCE' AND o.status='OPEN' AND r.sourceId=? AND r.scopeJson LIKE ?",v2[0],"%"+iid+"%");
  assertEquals(1,settlementDuty.size(),settlementDuty.toString());assertEquals(actor,settlementDuty.getFirst().get("ownerid"));assertNotNull(settlementDuty.getFirst().get("nextaction"));assertNotNull(settlementDuty.getFirst().get("nextcheckat"));
  // The logistics deficit is waived by a MANAGER ("customer accepts 28"); the settlement difference keeps its own owner.
  String assignment=deficit("OPEN").get("id").toString();var approval=effectsOf(waiverDecision("manager","decideQuantityDutyWaiver",assignment,"APPROVE","고객이 28을 수용했다"));var waiveRequest=envelope("waiveObligation",map("assignmentId",assignment,"reason","고객이 28을 수용했다"),revision(assignment));waiveRequest.put("approvalId",approval.get("approvalId"));assertEquals("APPLIED",apply(waiveRequest).get("outcome"));
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE kind='SETTLEMENT_DIFFERENCE' AND status='OPEN'"));
  // The adjustment path targets that open duty instead of REJECTED SETTLEMENT_DIFFERENCE_NOT_OPEN.
  var adjustment=map("invoiceId",iid,"mode","PROPOSE","amount","-2","currency","KRW","reason","정정 인도 28에 맞춘 감액","occurredAt",now.toString(),"externalEventId",id());String[] adjustmentProof=invoiceFact(iid,"SETTLEMENT_ADJUSTMENT",write(adjustment),null);
  var proposed=apply(envelope("recordSettlementAdjustment",map("invoiceId",iid,"mode","PROPOSE","amount",map("value","-2","currency","KRW"),"reason","정정 인도 28에 맞춘 감액","evidence",adjustmentProof[0],"canonicalOccurrenceId",adjustmentProof[1]),1));assertEquals("APPLIED",proposed.get("outcome"),proposed.toString());
  // Reprocessing the same correction does not open a second settlement root.
  runtime.requestContext().run(ctx->{return new org.springframework.transaction.support.TransactionTemplate(transactions).execute(st->settlementReview.getObject().contributionChanged(c(),v2[0]));});
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_responsibility_Roots WHERE kind='SETTLEMENT_DIFFERENCE'"));}
