 // Emergency reassignment is a separate ADMIN command with reason and audit; no approval row, no handover acceptance.
 @Test void emergencyReassignIsADesignatedAdminCommandWithReasonAndAuditAndNoApproval(){
  String admin=seedHuman("admin",List.of("emergencyReassign","getWork"),List.of("emergencyReassign"));String standby=seedHuman("standby",List.of("getWork"),List.of());
  String open=duty("RETURN_QC_REVIEW");int before=workRevision();int dutyRevision=revision(open);
  var slots=map("workId",work,"newOwnerId",standby,"reason","기존 담당 부재로 즉시 후속 대응");
  // The capability alone (the owner holds emergencyReassign) is not the ADMIN designation.
  var undesignated=apply(envelope("emergencyReassign",slots,before));assertEquals("REJECTED",undesignated.get("outcome"),undesignated.toString());assertEquals("FORBIDDEN",code(undesignated));
  var noReason=as("admin",()->apply(envelope("emergencyReassign",map("workId",work,"newOwnerId",standby),before)));assertEquals("REJECTED",noReason.get("outcome"),noReason.toString());assertEquals("TYPE_INVALID",code(noReason));
  var stale=as("admin",()->apply(envelope("emergencyReassign",slots,before+7)));assertEquals("CONFLICT",stale.get("outcome"),stale.toString());assertEquals("STALE_REVISION",code(stale));
  assertEquals(actor,jdbc.queryForObject("SELECT ownerId FROM mulino_work_read_Works WHERE ID=?",String.class,work));
  var done=as("admin",()->apply(envelope("emergencyReassign",slots,before)));assertEquals("APPLIED",done.get("outcome"),done.toString());assertEquals(work,done.get("workId"));
  var effect=effectsOf(done);assertEquals(actor,effect.get("previousOwnerId"));assertEquals(standby,effect.get("ownerId"));assertEquals(false,effect.get("handoverAccepted"));assertEquals(List.of(open),effect.get("reassignedAssignmentIds"));
  assertEquals(standby,jdbc.queryForObject("SELECT ownerId FROM mulino_work_read_Works WHERE ID=?",String.class,work));
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_work_read_ObligationReferences WHERE ID=? AND ownerId=? AND status='OPEN' AND revision=? AND basis=?",open,standby,dutyRevision+1,"EMERGENCY: 기존 담당 부재로 즉시 후속 대응"));
  assertEquals(1,count("SELECT COUNT(*) FROM mulino_commands_CommandAudits WHERE actorId=? AND capabilityId='emergencyReassign' AND outcome='APPLIED' AND commandId=?",admin,done.get("commandId")));
  assertEquals(0,count("SELECT COUNT(*) FROM mulino_commands_Approvals"));assertEquals(0,count("SELECT COUNT(*) FROM mulino_responsibility_Handovers"));
  var again=as("admin",()->apply(envelope("emergencyReassign",map("workId",work,"newOwnerId",standby,"reason","중복"),workRevision())));assertEquals("REJECTED",again.get("outcome"),again.toString());}

 // ---- s4h-sales review fixes (plan §4.2, §4.3, §5.3, §6, §7.1, §13.3 E1). Each test fails on 2e1d90cc. ----
 @Autowired ApplicationQueries queries;
 Map<String,Object> read(String operation,String target,Map<String,Object> scope,Instant asOf,Instant known){var body=map("scope",scope,"asOf",asOf.toString(),"knownAt",known.toString());if(target!=null)body.put("id",target);return runtime.requestContext().run(ctx->{return queries.query(QueryRequests.parse(operation,body));});}
 String allocationState(String allocation){return jdbc.queryForObject("SELECT state FROM mulino_inventory_SegmentAllocations WHERE ID=?",String.class,allocation);}
 int allocationRevision(String allocation){return count("SELECT revision FROM mulino_inventory_SegmentAllocations WHERE ID=?",allocation);}
 /** A current human whose capabilities are scoped to the given scope rows only (organization grant, narrower assignments). */
 String scopedHuman(String subject,List<String> caps,String scopeKind,List<String> scopeIds){String a=id(),g=id();insert("mulino_identity_Actors",map("organizationId",org,"ID",a,"kind","HUMAN","stableRequestOwner",a));insert("mulino_identity_AuthorityFences",map("organizationId",org,"actorId",a,"revision",1));insert("mulino_identity_ExternalIdentities",map("organizationId",org,"ID",id(),"actorId",a,"issuer","https://fixture.invalid","subject",subject,"organizationAlias",org));
  insert("mulino_identity_Memberships",map("organizationId",org,"ID",id(),"actorId",a,"validFrom",Timestamp.from(now.minusSeconds(1000)),"validUntil",Timestamp.from(now.plusSeconds(10000))));insert("mulino_identity_Grants",map("organizationId",org,"ID",g,"actorId",a,"delegatorId",a,"validFrom",Timestamp.from(now.minusSeconds(1000)),"validUntil",Timestamp.from(now.plusSeconds(10000))));insert("mulino_identity_GrantScopes",map("organizationId",org,"grantId",g,"scopeKind","ORGANIZATION","scopeId",org));
  for(String cap:caps){for(String scopeId:scopeIds)insert("mulino_identity_CapabilityAssignments",map("organizationId",org,"ID",id(),"actorId",a,"capabilityId",cap,"scopeKind",scopeKind,"scopeId",scopeId,"validFrom",Timestamp.from(now.minusSeconds(1000)),"validUntil",Timestamp.from(now.plusSeconds(10000))));insert("mulino_identity_GrantActions",map("organizationId",org,"grantId",g,"capabilityId",cap));}
  // Eligibility evidence is read with the caller's own getEvidence authority.
  insert("mulino_identity_CapabilityAssignments",map("organizationId",org,"ID",id(),"actorId",a,"capabilityId","getEvidence","scopeKind","ORGANIZATION","scopeId",org,"validFrom",Timestamp.from(now.minusSeconds(1000)),"validUntil",Timestamp.from(now.plusSeconds(10000))));insert("mulino_identity_GrantActions",map("organizationId",org,"grantId",g,"capabilityId","getEvidence"));return a;}
 /** Full delivery of the dispatched range with explicit occurrence time, returning {deliveryId, firstEventId, external, canonical}. */
 String[] deliverOriginal(Map<String,Object> content){String ids=intakeDelivery(content);var review=matchDelivery(content,ids);assertEquals("APPLIED",review.get("outcome"),review.toString());run("linkCanonicalOccurrence",map("reconciliationId",review.get("id")),1);String original=canonicalOf(ids.split("\\|")[0]);run("recordDelivery",map("observationId",content.get("physicalScopeId"),"canonicalOccurrenceId",original),1);
  return new String[]{jdbc.queryForObject("SELECT ID FROM mulino_trade_sales_Deliveries WHERE observationId=?",String.class,content.get("physicalScopeId")),jdbc.queryForObject("SELECT eventId FROM mulino_evidence_Claims WHERE ID=?",String.class,ids.split("\\|")[0]),ids.split("\\|")[2],original};}
