 // s4-sales-00 (plan §4.2, §6): a dispatch dated inside an earlier hold window is not laundered by current eligibility.
 @Test void dispatchDatedInsideAnEarlierHoldWindowIsRejectedWithZeroEffect(){allow("100");allowDispatch();Instant t0=now;String allocation=reserve("0","20");run("pickQuantity",map("allocationId",allocation),0);
  now=t0.plusSeconds(10);hold("100");assertEquals("SUSPENDED",allocationState(allocation));String restriction=jdbc.queryForObject("SELECT ID FROM mulino_inventory_Restrictions",String.class);
  now=t0.plusSeconds(20);String released=evidence(map("segmentId",segment,"operation","releaseHold","restrictionId",restriction),"RELEASE_QC");run("releaseHold",map("restrictionId",restriction,"evidenceId",released,"reason","QC resolved"),0);
  now=t0.plusSeconds(30);String replacement=effects(run("replaceAllocation",map("allocationId",allocation,"segmentId",segment,"startQuantity","0","quantity","20","unit","EA"),allocationRevision(allocation))).get("allocationId").toString();run("pickQuantity",map("allocationId",replacement),0);
  int movements=count("SELECT COUNT(*) FROM mulino_inventory_QuantityMovements");
  // Dated inside the hold window or before it: both precede the authorized pick of the replacement, so neither is this command's effect.
  for(Instant at:List.of(t0.plusSeconds(15),t0.plusSeconds(5))){var denied=apply(envelope("dispatchQuantity",map("allocationId",replacement,"transitPlaceId",transit,"occurredAt",at.toString(),"evidenceRef","late paperwork"),allocationRevision(replacement)));assertEquals("REJECTED",denied.get("outcome"),denied.toString());assertEquals("TYPE_INVALID",code(denied));}
  assertEquals(movements,count("SELECT COUNT(*) FROM mulino_inventory_QuantityMovements"));assertEquals(0,count("SELECT COUNT(*) FROM mulino_inventory_Dispatches"));assertEquals("EXECUTABLE",allocationState(replacement));
  var current=apply(envelope("dispatchQuantity",map("allocationId",replacement,"transitPlaceId",transit,"occurredAt",now.toString(),"evidenceRef","synthetic dispatch"),allocationRevision(replacement)));assertEquals("APPLIED",current.get("outcome"),current.toString());assertEquals("CONSUMED",allocationState(replacement));}

